const ROSTER_FLAT = Object.entries(ROSTER).flatMap(([d, ns]) => ns.map(n => d + " / " + n));

let missions = loadJSON('missions.json', []);
// a deploy/restart kills in-flight missions — say so instead of showing 'running' forever
missions.forEach(m => { if (m.status === 'running' || m.status === 'queued') { m.status = 'interrupted'; m.error = 'server restarted mid-mission (deploy). Re-run it with start_mission.'; } });
saveJSON('missions.json', missions);
let activeMission = null;              // mission id currently running
let missionQueue = Promise.resolve();  // one at a time — activeMission is global

function saveMissions() { missions = missions.slice(-40); saveJSON('missions.json', missions); }

function newMission(goal) {
  const m = { id: crypto.randomBytes(4).toString('hex'), goal, status: 'queued',
              started: Date.now(), steps: [], result: '', error: '' };
  missions.push(m); saveMissions(); return m;
}

function logWork(agent, dept, summary, output) {
  const m = missions.find(x => x.id === activeMission);
  if (!m) return 'No mission is running, so there was nothing to log against.';
  m.steps.push({ agent, dept: dept || '', summary: summary || '',
                 output: (output || '').slice(0, 1200), ts: Date.now() });
  saveMissions();
  return 'Logged to ' + agent + ' (step ' + m.steps.length + ').';
}

function missionBrief(goal) {
  return `MISSION: ${goal}

You are running this across Gavriel's agent map — 159 specialist agents in 10 departments.
Work the mission for real with your tools (web_search, read_page, send_email, list_inbox...). The cloud browser is offline — do not use browse_open; web_search + read_page cover research.

As you go, call log_work for EVERY meaningful piece of work, choosing the agent from the map whose
job it actually was. Use the exact agent name. This is what lights up his map, so log honestly:
one entry per real piece of work, with the actual finding in \`output\`, not a promise to do it.

Agents available:
${ROSTER_FLAT.join(', ')}

Your LAST action must be send_email to the owner with the full report (findings, numbers, links, next steps). Then finish with a two-line spoken-style summary.`;
}

async function runMission(m) {
  activeMission = m.id;
  m.status = 'running'; saveMissions();
  try {
    m.result = await brain([{ role: 'user', content: missionBrief(m.goal) }], true);
    m.status = 'done';
  } catch (e) {
    m.status = 'failed'; m.error = e.message;
    console.error('mission ' + m.id + ' failed:', e.message);
  }
  m.finished = Date.now();
  activeMission = null;
  saveMissions();
  // Guaranteed delivery: every mission mails its report home, even if the model
  // ran out of steam before calling send_email itself.
  try {
    if (mailer && OWNER_MAIL) {
      const lines = m.steps.map(st => '• ' + st.agent + ' (' + st.dept + '): ' + st.summary +
        (st.output ? '\n    ' + st.output : '')).join('\n\n');
      await sendMail(OWNER_MAIL,
        'Mission report: ' + (m.goal || '').slice(0, 70),
        'MISSION: ' + m.goal + '\nSTATUS: ' + m.status + '\n\n' +
        (m.result ? 'SUMMARY:\n' + m.result + '\n\n' : '') +
        (lines ? 'AGENT WORK LOG:\n' + lines : 'No agent steps were logged.') +
        (m.error ? '\n\nERROR: ' + m.error : ''));
    }
  } catch (e) { console.error('mission report mail failed:', e.message); }
  // she announces the outcome herself, out loud
  pushAlert('mission', m.status === 'done'
    ? 'Gavriel — mission done: ' + (m.goal || '').slice(0, 90) + '. Full report is in your inbox. Highlights: ' + (m.result || '').slice(0, 260)
    : 'Gavriel, the mission "' + (m.goal || '').slice(0, 70) + '" hit a wall: ' + (m.error || 'unknown error') + '. Say the word and I retry.');
}

// ---------- scheduled tasks (persistent cron) ----------
let tasks = loadJSON('tasks.json', []);
const jobs = new Map();
function armTask(t) {
  if (jobs.has(t.id)) { jobs.get(t.id).stop(); jobs.delete(t.id); }
  if (!t.active || !cron.validate(t.cron)) return;
  const job = cron.schedule(t.cron, () => runTask(t).catch(e => console.error('task', t.id, e.message)),
    { timezone: t.tz || process.env.TZ || 'America/New_York' });
  jobs.set(t.id, job);
}
async function runTask(t) {
  // A scheduled run has NO conversation context — only this instruction. So the
  // instruction must already contain every detail (who, what, when). It runs
  // autonomously with all her tools.
  t.lastRun = Date.now(); t.running = true; saveJSON('tasks.json', tasks);
  try {
    const out = await brain([{ role: 'user', content:
      'SCHEDULED TASK — run it fully and autonomously right now, no questions, no waiting for approval. ' +
      'Everything you need is in this instruction:\n\n' + t.instruction }], true);
    t.lastResult = (out || 'done').slice(0, 600);
    t.lastOk = true;
    // she tells him herself — a reminder is only a reminder if she SAYS it
    pushAlert('task', (out && out.length < 260) ? out
      : 'Done: ' + (t.instruction || '').slice(0, 90) + (out ? ' — ' + out.slice(0, 160) : ''));
  } catch (e) {
    t.lastResult = 'ERROR: ' + e.message;
    t.lastOk = false;
    console.error('task', t.id, 'failed:', e.message);
  }
  t.running = false; saveJSON('tasks.json', tasks);
  if (t.count) { t.count -= 1; if (t.count <= 0) { t.active = false; armTask(t); saveJSON('tasks.json', tasks); } }
}
function scheduleTask(instruction, cronExpr, count) {
  if (!cron.validate(cronExpr)) throw new Error('bad cron: ' + cronExpr);
  const t = { id: crypto.randomBytes(4).toString('hex'), instruction, cron: cronExpr, count: count || null, active: true, ts: Date.now() };
  tasks.push(t); saveJSON('tasks.json', tasks); armTask(t); return t;
}
tasks.forEach(armTask); // re-arm on boot

// ============================================================
//  JARVIS ALERTS — she speaks FIRST.
//  Anything worth his attention lands in this queue; the app polls it and
//  Nova says it out loud, unprompted. Defensive everywhere: an alert failure
//  must never take down the brain.
// ============================================================
let alerts = loadJSON('alerts.json', []);   // {id, kind, text, at, said}
function pushAlert(kind, text) {
  try {
    if (!text || !String(text).trim()) return;
    alerts.push({ id: crypto.randomBytes(4).toString('hex'), kind, text: String(text).trim().slice(0, 900), at: Date.now(), said: false });
    alerts = alerts.slice(-30);
    saveJSON('alerts.json', alerts);
  } catch (e) {}
}

// -- watch the inbox: a real email worth his attention → she tells him --
const OWN_ADDR = (process.env.SMTP_USER || '').toLowerCase();
let inboxSeen = new Set(), inboxWatchStart = Date.now();
async function watchInbox() {
  if (!inboxReady()) return;
  try {
    const list = await listInbox({ limit: 10, unreadOnly: true, days: 1 });
    for (const m of list) {
      if (inboxSeen.has(m.uid)) continue;
      inboxSeen.add(m.uid);
      const when = new Date(m.date).getTime() || 0;
      if (when < inboxWatchStart - 5 * 60000) continue;                  // old mail — not news
      const from = m.from || '', subj = m.subject || '';
      if (OWN_ADDR && from.toLowerCase().includes(OWN_ADDR)) continue;   // her own BCC copies
      if (/no-?reply|noreply|newsletter|unsubscribe|notifications?@|mailer|do-?not-?reply|updates@|info@/i.test(from)) continue;
      const who = from.replace(/<[^>]*>/, '').replace(/"/g, '').trim() || from;
      pushAlert('email', 'Gavriel, new email from ' + who + ' — "' + subj.slice(0, 90) + '". Want me to read it?');
    }
    if (inboxSeen.size > 500) inboxSeen = new Set([...inboxSeen].slice(-200));
  } catch (e) {}
}
setInterval(watchInbox, 5 * 60000);
setTimeout(watchInbox, 45000);

// -- morning brief: she opens the day herself (BRIEF_CRON to change the hour) --
const BRIEF_CRON = process.env.BRIEF_CRON || '30 7 * * *';
if (cron.validate(BRIEF_CRON)) {
  cron.schedule(BRIEF_CRON, async () => {
    try {
      const out = await brain([{ role: 'user', content:
        "MORNING BRIEF — you are opening Gavriel's day, unprompted, like JARVIS opens Tony's. Do it all yourself right now: " +
        "1) web_search today's weather in Lakewood NJ — one useful line. " +
        "2) list_inbox unread from the last day; read only what actually matters and triage: what needs him, what can wait. " +
        "3) list_tasks — anything firing today, mention it. " +
        "Then write the brief as 4-6 short SPOKEN lines — warm, sharp, a little wit. No markdown, no bullet symbols, no links." }], true);
      if (out) pushAlert('brief', out);
    } catch (e) { console.error('brief:', e.message); }
  }, { timezone: OWNER_TZ });
}

